description:
[
  {
    "topic": "US inflation prints (CPI/PPI/PCE) and their revisions",
    "why_gold_cares": "Shifts expected Fed path and real yields; gold is a zero-coupon real-rate asset",
    "impact_threshold": "Core surprise vs consensus large enough to move front-end rate-cut pricing meaningfully",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Labor market data (NFP, claims, JOLTS) and consumption data (retail sales)",
    "why_gold_cares": "Growth/labor weakness pulls forward cuts, lowers real yields and DXY; strength does the opposite",
    "impact_threshold": "Headline miss beyond typical forecast dispersion or sharp claims trend break",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Fed communication: speakers, minutes, Jackson Hole guidance",
    "why_gold_cares": "Directly reprices the policy path and term premium; hawkish tone lifts real yields, pressuring gold",
    "impact_threshold": "Voting members/Chair changing tone on timing or terminal rate, not repeating prior script",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Treasury auctions and refunding/issuance mix, TGA rebuild",
    "why_gold_cares": "Weak demand raises long-end yields and can raise fiscal-risk premium; heavy bill issuance drains reserves and tightens dollar liquidity",
    "impact_threshold": "Notable tail vs when-issued, weak indirect bid, or rapid reserve drain accompanied by funding-rate pressure",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "US dollar index direction and FX intervention headlines (JPY, CNY)",
    "why_gold_cares": "Gold is dollar-denominated; broad DXY moves transmit almost immediately in the intraday window",
    "impact_threshold": "Sustained directional DXY move rather than range-bound chop around a round level",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Geopolitical shocks: Middle East, Russia/Ukraine, ceasefire or escalation",
    "why_gold_cares": "Safe-haven demand and oil-linked inflation risk; ceasefires unwind the same premium",
    "impact_threshold": "New military action, strikes on energy infrastructure, or a signed/collapsed truce reported by a major wire",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Trade policy: tariffs, export controls, sanctions announcements",
    "why_gold_cares": "Stagflationary risk pricing plus reserve-diversification demand; can also spike dollar demand",
    "impact_threshold": "Formal orders or retaliation on major trading partners, not rhetoric",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Banking/credit stress and funding market dislocation",
    "why_gold_cares": "Flight-to-quality bid plus expected Fed easing/liquidity backstops",
    "impact_threshold": "Institution-specific failure, deposit flight, or persistent repo/SOFR spikes",
    "directional_risk": "BULLISH_GOLD"
  }
]
